        </section>
        <aside ref="basketElement" tabindex="-1" class="panel sales-basket" aria-label="本次已选清单" data-sales-basket>
          <div class="section-head"><h2>本次已选</h2><span>{{validation.physicalCount}} 件商品 · {{validation.serviceCount}} 项服务</span></div>
          <p v-if="!draft.goods.length&&!draft.services.length" class="muted empty-basket">查看商品不会自动加入清单。</p>
          <article v-for="row in validation.goods" :key="row.line.id" class="basket-row" :data-sales-position="row.line.id">
            <div class="section-head"><button class="product-link" @click="browseSku(row.line.skuId,row.line.id)">{{row.summary.name}}</button><el-button link :disabled="!canEdit||businessPending" :aria-label="`更换 ${row.summary.name}`" @click="openReplacement(row.line.id)">更换</el-button><el-button link type="danger" :disabled="!canEdit||businessPending" :aria-label="`移除 ${row.summary.name}`" @click="removePosition(row.line.id)">移除</el-button></div>
            <p class="muted">{{displaySpec(row.line.skuId,row.summary.spec)}}</p><small v-if="originLabel(row.line.id)">{{originLabel(row.line.id)}} <el-button link size="small" :disabled="!canEdit||businessPending" @click="openSource(row.line.id)">重新选择来源</el-button></small>
            <div class="quantity-line"><el-input-number :model-value="row.line.quantity" :min="1" :max="999999" :precision="0" size="small" :disabled="!canEdit||businessPending" :aria-label="`${row.summary.name} 数量`" @change="(value:number|undefined)=>changeQuantity(row.line.id,value)"/><el-tag v-if="row.line.role==='host'" size="small" type="info">手机实物</el-tag></div>
            <p v-for="issue in issuesFor(row.line.id,row.line.skuId)" :key="issue.code+issue.message" class="line-issue">{{issue.message}}</p>
            <details v-for="issue in conditionsFor(row.line.id)" :key="issue.confirmationKey"><summary>核对使用条件</summary><p>{{issue.message}}</p><ul><li v-for="condition in conditionDetail(issue)?.conditions||[]" :key="condition.label">{{condition.label}}</li></ul><el-input v-model="conditionNotes[issue.confirmationKey!]" type="textarea" :rows="2" placeholder="本次如何满足条件" aria-label="本次条件确认说明"/><el-button size="small" @click="confirmCondition(row.line.id,issue)">确认本次条件</el-button></details>
          </article>
          <article v-for="service in draft.services" :key="service.id" class="basket-row" :data-sales-service="service.id"><div class="section-head"><strong>{{service.name}}</strong><el-button link :disabled="!canEdit||businessPending" :aria-label="`更换 ${service.name}`" @click="openReplacement(service.id)">更换</el-button><el-button link type="danger" :disabled="!canEdit||businessPending" @click="removePosition(service.id)">移除</el-button></div><p class="muted">{{service.description}} {{service.validity}}</p><small v-if="originLabel(service.id)">{{originLabel(service.id)}} <el-button link size="small" :disabled="!canEdit||businessPending" @click="openSource(service.id)">重新选择来源</el-button></small><p v-for="issue in issuesFor(service.id,'')" :key="issue.code+issue.message" class="line-issue">{{issue.message}}</p><div class="quantity-line"><el-input-number :model-value="service.quantity" :min="1" :max="999999" :precision="0" size="small" :disabled="!canEdit||businessPending" :aria-label="`${service.name} 数量`" @change="(value:number|undefined)=>changeServiceQuantity(service.id,value)"/><small>{{service.unit}} · {{service.measurement==='per-delivery'?'本次交付':'每份方案'}}</small></div></article>
          <div class="basket-quote"><div class="section-head"><strong>{{formatBenefitCents(draft.quote.amountCents)}}</strong><el-button link @click="quoteOpen=!quoteOpen">{{quoteOpen?'收起报价':'填写报价'}}</el-button></div><div v-if="quoteOpen" class="quote-editor"><el-input v-model="quoteText" inputmode="decimal" placeholder="待报价" aria-label="本次方案报价" @compositionstart="quoteComposing=true" @compositionend="quoteComposing=false" @keydown.enter="commitQuote" @blur="commitQuote" clearable/><el-button :disabled="quoteComposing||!canEdit||businessPending" @click="reviewQuote">核对报价</el-button></div><small v-if="validation.quoteNeedsReview" class="line-issue">清单或依据变化，请重新核对报价。</small></div>
          <div v-if="inputError" class="line-issue" role="alert">{{inputError}}</div>
          <details v-if="otherIssues.length" class="checklist-issues"><summary>还有 {{otherIssues.length}} 项需要处理</summary><p v-for="issue in otherIssues" :key="issue.code+issue.message">{{issue.message}}</p></details>
          <div class="common-save"><el-button link :disabled="!canPersist||!store.can('product:benefit:create')||businessPending||commonSaving||!draft.goods.length&&!draft.services.length" :loading="commonSaving" @click="saveCommon">{{commonError?'重试存为常用组合':'存为常用组合'}}</el-button><p v-if="commonError" class="line-issue" role="alert">{{commonError}}</p></div>
          <div class="basket-actions"><el-button :disabled="!canPersist||businessPending||!draft.id&&!dirty" @click="saveScheme" data-sales-save>立即保存</el-button><el-button type="primary" :disabled="!canPersist||!store.can('product:delivery:create')||businessPending||!draft.goods.length&&!draft.services.length" :loading="businessPending" @click="checkout" data-sales-checkout>核对交付</el-button></div>
        </aside>
      </div>
    </template>
    <el-dialog v-model="deviceOpen" title="选择使用设备" width="min(580px,94vw)"><p class="muted">用于核对配件适用性，不会加入手机实物。</p><el-radio-group v-model="deviceMode"><el-radio-button value="sku">已有商品</el-radio-button><el-radio-button value="model">设备型号</el-radio-button></el-radio-group><el-select v-if="deviceMode==='sku'" v-model="deviceSkuChoice" filterable placeholder="选择具体手机规格" aria-label="选择使用设备商品"><el-option v-for="sku in deviceSkus" :key="sku.skuId" :value="sku.skuId" :label="`${sku.name} · ${sku.spec}`"/></el-select><DeviceModelPicker v-else v-model="deviceModelChoice" :options="models" label="选择已有设备型号"/><template #footer><el-button @click="deviceOpen=false">取消</el-button><el-button type="primary" :disabled="deviceMode==='sku'?!deviceSkuChoice:!deviceModelChoice" @click="confirmDevice">使用此设备</el-button></template></el-dialog>
    <el-dialog v-model="replacementOpen" title="更换清单项目" width="min(640px,95vw)" @closed="replacementId=''">
      <p class="muted">{{replacementService?'从当前来源的选配方案选择另一服务项目。确认后重新核对报价。':'在原用途内选择实际在售规格。确认后重新核对适用性与报价。'}}</p><el-input v-model="replacementSearch" clearable placeholder="搜索替换商品或规格" aria-label="搜索替换商品或规格"/>
      <el-radio-group v-model="replacementChoice" class="replacement-options"><el-radio v-for="option in replacementOptions.slice(0,replacementShown)" :key="option.key" :value="option.key" :disabled="!option.canAdd"><span>{{option.label}}</span><small>{{option.reason}}</small></el-radio></el-radio-group><p v-if="!replacementOptions.length" class="muted">{{legacyFramework?'此组合沿用原框架，请在高级详情中更换项目。':replacementService?'服务由选配项目定义，当前没有其他服务项目；可调整数量或移除。':'当前用途没有可更换的实际商品，请核对来源或配置范围。'}}</p><el-button v-if="legacyFramework" link type="primary" @click="replacementOpen=false;openAdvanced()">高级详情</el-button><el-button v-if="replacementOptions.length>replacementShown" link @click="replacementShown+=12">继续查看替换候选</el-button><p v-if="inputError" class="line-issue">{{inputError}}</p><template #footer><el-button @click="replacementOpen=false">取消</el-button><el-button type="primary" :disabled="!replacementChoice||!canEdit||businessPending" @click="confirmReplacement">确认更换</el-button></template>
    </el-dialog>
    <el-dialog v-model="sourceOpen" title="重新选择来源" width="min(580px,94vw)"><p class="muted">仅列出能承接此商品用途的清单位置；确认会建立新位置与适用依据。</p><el-select v-model="sourceChoice" aria-label="新的来源商品" placeholder="选择清单中的来源" filterable><el-option v-for="option in sourceOptions" :key="option.id" :value="option.id" :label="option.label"/></el-select><p v-if="!sourceOptions.length" class="muted">暂无可用来源，请先加入来源商品。</p><p v-if="inputError" class="line-issue">{{inputError}}</p><template #footer><el-button @click="sourceOpen=false">取消</el-button><el-button type="primary" :disabled="!sourceChoice||!canEdit||businessPending" @click="confirmSource">确认来源</el-button></template></el-dialog>
    <el-drawer v-model="recordsOpen" title="已保存方案" size="min(620px,95vw)"><p v-if="!savedSchemes.length" class="muted">尚无销售方案。</p><div v-for="record in savedSchemes" :key="record.id" class="record-row"><div><strong>{{record.name}}</strong><p class="muted">{{record.code}} · {{record.goods.length}} 项商品 · {{record.services.length}} 项服务</p></div><div class="record-actions"><el-button @click="openSaved(record)">打开</el-button><el-button v-if="canUseCommon(record)" link @click="useCommon(record)">复制为新方案</el-button></div></div></el-drawer>
    <el-drawer v-model="commonOpen" title="常用组合" size="min(620px,95vw)"><p v-if="!commonSchemes.length" class="muted">可在常用组合中收藏已保存的组合。</p><div v-for="record in commonSchemes" :key="record.id" class="record-row"><div><strong>{{record.name}}</strong><p class="muted">{{record.goods.length}} 项商品 · {{record.services.length}} 项服务</p></div><el-button v-if="canUseCommon(record)" @click="useCommon(record)">新方案使用</el-button><el-button v-else link @click="router.push(`/benefit-packages/${record.id}`)">查看历史组合</el-button></div></el-drawer>
    <button v-if="supported&&!missing" class="mobile-basket-shortcut" aria-label="查看本次已选清单" @click="focusBasket"><span>本次已选 {{validation.physicalCount+validation.serviceCount}}</span><strong>{{formatBenefitCents(draft.quote.amountCents)}}</strong><span>查看清单 ↑</span></button>
    <el-dialog v-model="deliveryOpen" title="核对交付清单" width="min(760px,96vw)" :close-on-click-modal="false"><template v-if="preview"><p>{{preview.packageName}} · {{formatBenefitCents(preview.quote.totalCents)}}</p><el-table :data="[...preview.goods.map(row=>({name:row.name,detail:row.spec,quantity:row.totalQuantity})),...preview.services.map(row=>({name:row.name,detail:row.validity,quantity:row.totalQuantity}))]"><el-table-column prop="name" label="商品 / 服务"/><el-table-column prop="detail" label="规格 / 约定"/><el-table-column prop="quantity" label="数量" width="80"/></el-table><p v-for="issue in preview.issues" :key="issue.code+issue.message" class="line-issue">{{issue.message}}</p><el-checkbox v-model="confirmed" :disabled="!preview.canConfirm">已核对商品、数量、适用条件与报价</el-checkbox></template><template #footer><el-button @click="deliveryOpen=false">继续选购</el-button><el-button type="primary" :disabled="!preview?.canConfirm||!confirmed||businessPending" :loading="businessPending" @click="generateDelivery" data-sales-generate>生成交付清单</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch, nextTick, onScopeDispose } from 'vue'
import { useRoute, useRouter, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHead from '../components/PageHead.vue'
import CategoryFilterTree from '../components/CategoryFilterTree.vue'
import SalesSkuSelector from '../components/sales-shopping/SalesSkuSelector.vue'
import SalesCandidateGroup from '../components/sales-shopping/SalesCandidateGroup.vue'
import DeviceModelPicker from '../components/compatibility/DeviceModelPicker.vue'
import { useSalesShoppingDraft } from '../components/sales-shopping/useSalesShoppingDraft'
import { categoryFilterCaption, categoryScopeIds } from '../domain/categoryTree'
import { categoryPath, shelfOf, projectAttrs } from '../domain/logic'
import { isRealSku } from '../domain/catalogIdentity'
import { familyBrandText, familyBrandValues, savedSkuCode, savedSkuSpec } from '../domain/productList'
import { compatibilityRecordRole, listDeviceModels } from '../domain/deviceResolution'
import { addBenefitSku, benefitSkuSummary, cloneBenefit, confirmBenefitCondition, parseBenefitAmount, reviewBenefitQuote, setBenefitDevice, setBenefitPositionQuantity } from '../domain/benefitPackages'
import { querySalesCandidates, addSalesCandidate, attachSalesSource, removeSalesPosition, createSalesCandidateIndex, setSalesDevice, replaceSalesPosition, reselectSalesSource, createSalesCommonCombinationDraft } from '../domain/salesSelection'
import type { BenefitDeviceContext, BenefitIssue, BenefitPackageDraft } from '../domain/benefitPackageTypes'
import type { SalesCandidate, SalesOptionItem } from '../domain/salesConfigurationTypes'
import { amountInput, formatBenefitCents, localBenefitRequest } from '../components/benefit-package/benefitPackagePresentation'

const router=useRouter(),route=useRoute()
const session=useSalesShoppingDraft()
const {store,draft,validation,businessPending,dirty,error,inputError,missing,canEdit,canPersist,saveState,saveLabel,preview,confirmed,change,clearInputError,retry}=session
const supported=computed(()=>draft.value.compositionVersion===2&&(!draft.value.sales||draft.value.sales.schemaVersion===1)&&(!draft.value.framework||['type-v1','type-v2'].includes(draft.value.framework.kind)))
const legacyFramework=computed(()=>!!draft.value.framework)
const keyword=ref(''),brand=ref(''),categoryIds=ref<string[]>([]),shownCount=ref(24),selectedFamilyId=ref(''),sourceSkuId=ref(''),sourcePositionId=ref<string>()
const trail=ref<{skuId:string;positionId?:string}[]>([])
const nameEditing=ref(false),nameText=ref(''),nameComposing=ref(false),nameInput=ref<{focus:()=>void}>(),recordsOpen=ref(false),commonOpen=ref(false),deliveryOpen=ref(false),quoteOpen=ref(false),quoteText=ref(''),quoteComposing=ref(false),quoteError=ref('')
const basketElement=ref<HTMLElement>(),commonSaving=ref(false),commonError=ref('')
const replacementOpen=ref(false),replacementId=ref(''),replacementChoice=ref(''),replacementSearch=ref(''),replacementShown=ref(12),sourceOpen=ref(false),sourceChoice=ref('')
const deviceOpen=ref(false),deviceMode=ref<'sku'|'model'>('sku'),deviceSkuChoice=ref(''),deviceModelChoice=ref(''),conditionNotes=ref<Record<string,string>>({})
if(typeof route.query.scheme==='string')session.loadInitial(route.query.scheme)
const initialCopy=route.query.copy==='1'&&!!draft.value.id&&supported.value&&!missing.value
if(initialCopy)void session.replaceSession(draft.value,true,true)
quoteText.value=amountInput(draft.value.quote.amountCents)
const realSkus=computed(()=>store.data.skus.filter(sku=>isRealSku(store.data,sku)&&sku.status==='on_sale'&&shelfOf(store.data.families.find(family=>family.id===sku.familyId)!)==='online'))
const skuByFamily=computed(()=>{const map=new Map<string,typeof realSkus.value>();for(const sku of realSkus.value){const rows=map.get(sku.familyId)||[];rows.push(sku);map.set(sku.familyId,rows)}return map})
const familySkus=(id:string)=>skuByFamily.value.get(id)||[]
const attributeLabels=computed(()=>new Map(store.data.params.map(param=>[param.id,param.name])))
function displaySpec(id:string,fallback=''){const sku=store.data.skus.find(item=>item.id===id),family=sku&&store.data.families.find(item=>item.id===sku.familyId);return sku&&family?Object.entries(projectAttrs(family,sku)).filter(([,value])=>value.trim()).map(([key,value])=>`${attributeLabels.value.get(key)||key} ${value}`).join(' · ')||fallback:fallback}
const brands=computed(()=>[...new Set(store.data.families.flatMap(family=>familyBrandValues(store.data,family)))].sort((a,b)=>a.localeCompare(b,'zh')))
const categoryCaption=computed(()=>categoryFilterCaption(store.data.categories,categoryIds.value,true))
const invalidCategoryIds=computed(()=>categoryIds.value.filter(id=>!store.data.categories.some(category=>category.id===id)))
const categoryRange=computed(()=>new Set(categoryIds.value.flatMap(id=>categoryScopeIds(store.data.categories,id,'with-children'))))
const families=computed(()=>{if(invalidCategoryIds.value.length)return [];const term=keyword.value.trim().toLocaleLowerCase();return store.data.families.filter(family=>{const skus=familySkus(family.id);return skus.length&&(!categoryIds.value.length||categoryRange.value.has(family.categoryId))&&(!brand.value||familyBrandValues(store.data,family).includes(brand.value))&&(!term||`${family.name} ${skus.map(sku=>`${savedSkuCode(sku)} ${savedSkuSpec(family,sku)} ${sku.skuName||''}`).join(' ')}`.toLocaleLowerCase().includes(term))})})
const shownFamilies=computed(()=>families.value.slice(0,shownCount.value)),selectedFamily=computed(()=>store.data.families.find(family=>family.id===selectedFamilyId.value))
watch([keyword,brand,categoryIds],()=>{shownCount.value=24})
const sourceSummary=computed(()=>benefitSkuSummary(store.data,sourceSkuId.value)),sourceRole=computed(()=>compatibilityRecordRole(store.data,sourceSkuId.value))
const candidateIndex=computed(()=>createSalesCandidateIndex(store.data))
const candidates=computed(()=>legacyFramework.value?{resolution:{state:'none' as const,message:'此组合沿用原框架，不叠加新的选配方案。增补商品请使用高级详情。',bindingIds:[],source:{state:'legacy' as const,skuId:sourceSkuId.value,modelId:'',versionId:'',identityKey:'',message:''},plan:undefined},rows:[] as SalesCandidate[]}:querySalesCandidates(store.data,draft.value,sourceSkuId.value,candidateIndex.value,sourcePositionId.value||undefined))
const candidateGroups=computed(()=>{const groups=new Map<string,{key:string;item:SalesOptionItem;rows:SalesCandidate[]}>();for(const item of candidates.value.resolution.plan?.items||[])if(item.enabled){const key=`${candidates.value.resolution.plan!.planId}:${item.id}`;groups.set(key,{key,item,rows:[]})}for(const row of candidates.value.rows){const key=`${row.plan?.planId||'related'}:${row.item.id}`;if(!groups.has(key))groups.set(key,{key,item:row.item,rows:[]});groups.get(key)!.rows.push(row)}return [...groups.values()].sort((a,b)=>a.item.order-b.item.order)})
const models=computed(()=>listDeviceModels(store.data))
const deviceSkus=computed(()=>realSkus.value.filter(sku=>compatibilityRecordRole(store.data,sku.id)==='host').map(sku=>benefitSkuSummary(store.data,sku.id)!))
const deviceLabel=computed(()=>draft.value.device?.kind==='sku'?benefitSkuSummary(store.data,draft.value.device.skuId)?.name||'设备已失效':draft.value.device?.kind==='model'?models.value.find(model=>JSON.stringify(model.host)===JSON.stringify(draft.value.device?.kind==='model'?draft.value.device.host:null))?.label||draft.value.device.host.steps.map(step=>step.valueId).join(' · '):'尚未指定')
const savedSchemes=computed(()=>(store.can('product:benefit:read')?store.data.benefitPackages||[]:[]).filter(record=>record.sales).slice().sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)))
const commonSchemes=computed(()=>(store.can('product:benefit:read')?store.data.benefitPackages||[]:[]).filter(record=>record.favorite&&record.status!=='disabled'))
const otherIssues=computed(()=>validation.value.issues.filter(issue=>!issue.positionId&&!issue.skuId&&issue.code!=='quote-review'))
function toggleCategory(id:string,multiple=false){categoryIds.value=multiple?(categoryIds.value.includes(id)?categoryIds.value.filter(value=>value!==id):[...categoryIds.value,id]):[id]}
function openFamily(id:string){selectedFamilyId.value=id;const skus=familySkus(id);if(skus.length===1)browseSku(skus[0]!.id);else if(!skus.some(sku=>sku.id===sourceSkuId.value)){sourceSkuId.value='';sourcePositionId.value=undefined;trail.value=[]}}
function browseSku(id:string,positionId?:string){const sku=store.data.skus.find(item=>item.id===id);if(!sku)return;if(positionId&&!draft.value.goods.some(line=>line.id===positionId&&line.skuId===id))positionId=undefined;selectedFamilyId.value=sku.familyId;sourceSkuId.value=id;sourcePositionId.value=positionId;const previous=trail.value.findIndex(item=>item.skuId===id&&item.positionId===positionId);trail.value=previous>=0?trail.value.slice(0,previous+1):[...trail.value,{skuId:id,positionId}].slice(-16)}
function returnToSource(index:number){const entry=trail.value[index];if(entry)browseSku(entry.skuId,entry.positionId)}
function apply(operation:(value:BenefitPackageDraft)=>BenefitPackageDraft){clearInputError();const accepted=change(operation);if(quoteError.value)inputError.value=quoteError.value;return accepted}
function chooseDevice(device:BenefitDeviceContext){if(apply(value=>legacyFramework.value?setBenefitDevice(store.data,value,device):setSalesDevice(store.data,value,device)))deviceOpen.value=false}
function confirmDevice(){if(deviceMode.value==='sku')chooseDevice({kind:'sku',skuId:deviceSkuChoice.value});else{const model=models.value.find(item=>item.key===deviceModelChoice.value);if(model)chooseDevice({kind:'model',host:cloneBenefit(model.host)})}}
function addCurrent(){if(legacyFramework.value)return;const id=sourceSkuId.value;if(!id)return;const accepted=apply(value=>{let next=value;if(sourceRole.value==='host'&&!next.device)next=setBenefitDevice(store.data,next,{kind:'sku',skuId:id});next=addBenefitSku(store.data,next,id,1,{role:sourceRole.value==='host'?'host':'item',groupId:null});const line=next.goods.find(item=>item.skuId===id&&item.groupId===null&&item.role===(sourceRole.value==='host'?'host':'item'));return attachSalesSource(store.data,next,id,line?.id)});if(accepted){const line=draft.value.goods.find(item=>item.skuId===id&&item.groupId===null&&item.role===(sourceRole.value==='host'?'host':'item'));if(line){sourcePositionId.value=line.id;const entry=trail.value[trail.value.length-1];if(entry?.skuId===id&&!entry.positionId)entry.positionId=line.id;else browseSku(id,line.id)}}}
function candidatePositions(candidate:SalesCandidate){return draft.value.sales?.origins.filter(origin=>origin.sourceSkuId===candidate.sourceSkuId&&origin.sourcePositionId===sourcePositionId.value&&origin.itemId===candidate.item.id&&origin.plan?.planId===candidate.plan?.planId&&origin.plan?.version===candidate.plan?.version).flatMap(origin=>[...draft.value.goods,...draft.value.services].filter(line=>line.id===origin.positionId&&(!candidate.skuId||'skuId' in line&&line.skuId===candidate.skuId)))||[]}
function candidateQuantity(candidate:SalesCandidate){return candidatePositions(candidate).reduce((total,line)=>total+line.quantity,0)}
function addCandidate(candidate:SalesCandidate){if(legacyFramework.value)return;apply(value=>addSalesCandidate(store.data,value,candidate,{sourcePositionId:sourcePositionId.value}))}
function browseCandidate(candidate:SalesCandidate){if(candidate.skuId)browseSku(candidate.skuId,candidatePositions(candidate)[0]?.id)}
function removePosition(id:string){if(apply(value=>removeSalesPosition(value,id))){if(sourcePositionId.value===id)sourcePositionId.value=undefined;for(const key of Object.keys(conditionNotes.value))if(key.includes(id))delete conditionNotes.value[key]}}
function changeQuantity(id:string,value:number|undefined){if(value!==undefined)apply(current=>setBenefitPositionQuantity(store.data,current,id,value))}
function changeServiceQuantity(id:string,value:number|undefined){if(value===undefined)return;apply(current=>{const service=current.services.find(item=>item.id===id);if(!service||!Number.isSafeInteger(value)||value<1)throw Error('服务数量须为正整数。');service.quantity=value;current.confirmations=[];return current})}
function originLabel(id:string){const origin=draft.value.sales?.origins.find(item=>item.positionId===id);if(!origin)return '';return `${origin.plan?.items.find(item=>item.id===origin.itemId)?.name||'相关商品'} · 来自 ${benefitSkuSummary(store.data,origin.sourceSkuId)?.name||'来源已失效'}`}
function issuesFor(id:string,skuId:string){return validation.value.issues.filter(issue=>issue.severity!=='warning'&&issue.code!=='condition-confirmation'&&(issue.positionId===id||!issue.positionId&&issue.skuId===skuId))}
function conditionsFor(id:string){return validation.value.issues.filter(issue=>issue.code==='condition-confirmation'&&issue.positionId===id)}
function conditionDetail(issue:BenefitIssue){const row=validation.value.goods.find(item=>item.line.id===issue.positionId);return row?.compatibility.capabilities.find(detail=>JSON.stringify([row.line.id,row.line.skuId,detail.capability])===issue.confirmationKey)}
function confirmCondition(id:string,issue:BenefitIssue){const capability=conditionDetail(issue)?.capability;if(capability==='basic'||capability==='fast-charge')apply(value=>confirmBenefitCondition(store.data,value,id,conditionNotes.value[issue.confirmationKey!]||'',new Date().toISOString(),capability))}
function commitQuote(event?:Event){if(quoteComposing.value||event instanceof KeyboardEvent&&(event.isComposing||event.keyCode===229))return false;try{const amount=parseBenefitAmount(quoteText.value);quoteError.value='';clearInputError();if(amount===draft.value.quote.amountCents)return true;return apply(value=>{value.quote.amountCents=amount;value.quote.reviewedBasis='';return value})}catch(cause){quoteError.value=cause instanceof Error?cause.message:String(cause);inputError.value=quoteError.value;return false}}
function reviewQuote(){if(commitQuote())apply(value=>reviewBenefitQuote(value,store.data))}
async function editName(){nameText.value=draft.value.name||'销售方案';nameEditing.value=true;await nextTick();nameInput.value?.focus()}
function cancelName(event?:KeyboardEvent){if(nameComposing.value||event?.isComposing)return;nameEditing.value=false;nameText.value=draft.value.name}
function commitName(event?:Event){if(!nameEditing.value)return true;if(nameComposing.value||event instanceof KeyboardEvent&&(event.isComposing||event.keyCode===229))return false;const name=nameText.value.trim()||'销售方案';if(!apply(value=>({...value,name})))return false;nameEditing.value=false;return true}
async function saveScheme(){if(!commitName()||!commitQuote())return;if(await (error.value?session.retry():session.flush()))ElMessage.success('最新销售方案已保存')}
let changingRoute=false,skipNextRoute=false,sessionSwitching=false,routeGeneration=0,browsingGeneration=0,alive=true
onScopeDispose(()=>{alive=false;routeGeneration++})
function resetBrowsing(){browsingGeneration++;sourceSkuId.value='';sourcePositionId.value=undefined;selectedFamilyId.value='';trail.value=[];quoteText.value=amountInput(draft.value.quote.amountCents);quoteError.value='';conditionNotes.value={};nameEditing.value=false;replacementOpen.value=false;sourceOpen.value=false;commonError.value='';commonAttempt=undefined}
async function changeSession(source?:BenefitPackageDraft,copy=false){sessionSwitching=true;try{if(commitName()&&commitQuote()&&await session.replaceSession(source,copy))return true;if(businessPending.value)return false;try{await ElMessageBox.confirm('最新输入尚未保存，切换将放弃本页这些修改。','切换销售方案',{confirmButtonText:'放弃修改并切换',cancelButtonText:'继续处理',type:'warning'});return session.replaceSession(source,copy,true)}catch{return false}}finally{sessionSwitching=false}}
async function syncUrl(push=false){const query={...route.query};delete query.sku;delete query.copy;if(draft.value.id)query.scheme=draft.value.id;else delete query.scheme;changingRoute=true;try{await router[push?'push':'replace']({path:route.path,query})}finally{changingRoute=false}}
async function newSession(){if(await changeSession()){resetBrowsing();await syncUrl(true)}}
async function openSaved(record:BenefitPackageDraft){if(await changeSession(record)){resetBrowsing();recordsOpen.value=false;await syncUrl(true)}}
function canUseCommon(record:BenefitPackageDraft){return record.compositionVersion===2&&(!record.sales||record.sales.schemaVersion===1)&&(!record.framework||['type-v1','type-v2'].includes(record.framework.kind))}
async function useCommon(record:BenefitPackageDraft){if(!canUseCommon(record))return;if(await changeSession(record,true)){resetBrowsing();recordsOpen.value=false;commonOpen.value=false;await syncUrl(true)}}
watch(()=>draft.value.id,(id)=>{if(id&&!changingRoute&&!sessionSwitching&&route.query.scheme!==id)void syncUrl()})
onBeforeRouteUpdate(async(to,from)=>{if(skipNextRoute){skipNextRoute=false;return true}if(changingRoute)return true;const target=typeof to.query.scheme==='string'?to.query.scheme:'',previous=typeof from.query.scheme==='string'?from.query.scheme:'';if(target!==previous||to.query.copy==='1'){const epoch=++routeGeneration;const source=target?store.data.benefitPackages?.find(item=>item.id===target):undefined;if(!await changeSession(source,to.query.copy==='1'&&!!source)||epoch!==routeGeneration)return false;resetBrowsing();if(target&&!source)session.loadInitial(target);if(to.query.copy==='1'&&source){skipNextRoute=true;return {path:to.path,query:{...to.query,scheme:undefined,copy:undefined},replace:true}}}if(typeof to.query.sku==='string')browseSku(to.query.sku);return true})
watch(()=>route.query.sku,id=>{if(typeof id==='string')browseSku(id)},{immediate:true})
if(initialCopy)void syncUrl()
function focusBasket(){basketElement.value?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});basketElement.value?.focus({preventScroll:true})}
let commonAttempt:{key:string;draft:BenefitPackageDraft;requestId:string}|undefined
async function saveCommon(){if(commonSaving.value||!commitName()||!commitQuote()||!canPersist.value||!store.can('product:benefit:create'))return;commonSaving.value=true;commonError.value='';const owner=JSON.stringify([store.activeUserId,store.previewUserId]),id=draft.value.id,generation=browsingGeneration;const valid=()=>alive&&generation===browsingGeneration&&owner===JSON.stringify([store.activeUserId,store.previewUserId])&&(!id||id===draft.value.id)&&store.can('product:benefit:create');try{if(!await (error.value?session.retry():session.flush())||!valid())return;const key=JSON.stringify([draft.value.id,draft.value.revision,draft.value.name]);if(!commonAttempt||commonAttempt.key!==key)commonAttempt={key,draft:createSalesCommonCombinationDraft(draft.value,draft.value.name),requestId:localBenefitRequest('sales-common')};const result=await store.saveBenefitPackage({draft:cloneBenefit(commonAttempt.draft),status:'draft',expectedRevision:0,requestId:commonAttempt.requestId},valid);if(!valid())return;if(!result.ok){commonError.value=result.message||'保存失败，常用组合副本已保留，请重试。';return}ElMessage.success('已存为独立常用组合');commonAttempt=undefined}catch(cause){if(valid())commonError.value=cause instanceof Error?cause.message:'保存失败，请重试。'}finally{commonSaving.value=false}}
const replacementOrigin=computed(()=>draft.value.sales?.origins.find(origin=>origin.positionId===replacementId.value))
const replacementService=computed(()=>draft.value.services.some(item=>item.id===replacementId.value))
const replacementOptions=computed(()=>{if(!replacementOpen.value||legacyFramework.value)return [];const line=draft.value.goods.find(item=>item.id===replacementId.value),service=draft.value.services.find(item=>item.id===replacementId.value),origin=replacementOrigin.value;if(!line&&!service)return [];const term=replacementSearch.value.trim().toLocaleLowerCase();const rows=origin?querySalesCandidates(store.data,draft.value,origin.sourceSkuId,candidateIndex.value,origin.sourcePositionId).rows.filter(row=>(service?row.item.scope.kind==='service'&&row.item.id!==origin.itemId:row.item.id===origin.itemId&&row.skuId!==line!.skuId)&&row.plan?.planId===origin.plan?.planId&&row.plan?.version===origin.plan?.version).map(row=>({key:row.key,value:row as SalesCandidate|string,label:`${row.summary?.name||row.item.name} · ${row.skuId?displaySpec(row.skuId):''}`,canAdd:row.canAdd,reason:row.reason})):familySkus(line?benefitSkuSummary(store.data,line.skuId)?.familyId||'':'').filter(sku=>sku.id!==line?.skuId).map(sku=>({key:sku.id,value:sku.id as SalesCandidate|string,label:`${benefitSkuSummary(store.data,sku.id)?.name||sku.skuName} · ${displaySpec(sku.id)}`,canAdd:true,reason:savedSkuCode(sku)}));return rows.filter(row=>!term||`${row.label} ${row.reason}`.toLocaleLowerCase().includes(term))})
function openReplacement(id:string){clearInputError();replacementId.value=id;replacementChoice.value='';replacementSearch.value='';replacementShown.value=12;replacementOpen.value=true}
function confirmReplacement(){const option=replacementOptions.value.find(item=>item.key===replacementChoice.value);if(option&&apply(value=>replaceSalesPosition(store.data,value,replacementId.value,option.value,{sourcePositionId:replacementOrigin.value?.sourcePositionId}))){replacementOpen.value=false;if(sourcePositionId.value===replacementId.value)sourcePositionId.value=undefined}}
function openSource(id:string){clearInputError();replacementId.value=id;sourceChoice.value='';sourceOpen.value=true}
const sourceOptions=computed(()=>!sourceOpen.value||legacyFramework.value?[]:draft.value.goods.filter(line=>line.id!==replacementId.value).flatMap(line=>{try{reselectSalesSource(store.data,draft.value,replacementId.value,line.id);return [{id:line.id,label:`${benefitSkuSummary(store.data,line.skuId)?.name||line.skuId} · ${displaySpec(line.skuId)} · 位置 ${draft.value.goods.indexOf(line)+1}`}]}catch{return []}}))
function confirmSource(){if(apply(value=>reselectSalesSource(store.data,value,replacementId.value,sourceChoice.value)))sourceOpen.value=false}

async function openAdvanced(){if(!commitName()||!commitQuote())return;if(await (error.value?session.retry():session.flush())&&draft.value.id)await router.push(`/benefit-packages/${draft.value.id}`)}
async function checkout(){if(!commitName()||!commitQuote())return;if(await session.prepareDelivery())deliveryOpen.value=true}
async function generateDelivery(){const result=await session.generate();if(result.ok&&result.delivery)await router.push(`/benefit-packages/deliveries/${result.delivery.id}`)}
watch([()=>store.activeUserId,()=>store.previewUserId],()=>{quoteText.value=amountInput(draft.value.quote.amountCents);quoteError.value='';conditionNotes.value={};deliveryOpen.value=false;nameEditing.value=false;deviceOpen.value=false;recordsOpen.value=false;commonOpen.value=false;sourcePositionId.value=undefined;commonAttempt=undefined;commonError.value='';void syncUrl()})
onBeforeRouteLeave(async()=>{if(businessPending.value)return false;if(commitName()&&commitQuote()&&await session.flush())return true;try{await ElMessageBox.confirm('最新输入尚未保存。离开将放弃本页未保存的修改。','离开销售选购',{confirmButtonText:'放弃并离开',cancelButtonText:'继续处理',type:'warning'});return true}catch{return false}})
</script>

